#include "Window.h"
#include "LocalMultiplayer.h"
#include <cstdio>
#include <set>
int checks=0,failures=0;void Check(bool b,const char* text){++checks;failures+=!b;std::printf("%s %s\n",b?"PASS":"FAIL",text);}
int main(){Window window;SDL_SetHint(SDL_HINT_JOYSTICK_ALLOW_BACKGROUND_EVENTS,"1");if(!window.Init("M89 device routes",320,240,false))return 1;Check(window.Input().localDevices.expired(),"single-player window allocates no multiplayer device service");LocalPlayers players;players.devices=std::make_shared<InputDeviceHub>();window.Input().localDevices=players.devices;auto& hub=*players.devices;
 std::string error;const auto a=players.Create("A",InputMap::Defaults(),error)->id,b=players.Create("B",InputMap::Defaults(),error)->id;
 players.Assign(a,hub,{"mouse",{}, {0,0,1,1}},error);players.Assign(b,hub,{"touch",{}, {.5f,0,.5f,1}},error);window.PollEvents();players.Route(hub);
 SDL_Event touch{};touch.type=SDL_FINGERDOWN;touch.tfinger.touchId=77;touch.tfinger.fingerId=88;touch.tfinger.x=.75f;touch.tfinger.y=.5f;touch.tfinger.pressure=1;SDL_PushEvent(&touch);SDL_Event synthetic{};synthetic.type=SDL_MOUSEBUTTONDOWN;synthetic.button.which=SDL_TOUCH_MOUSEID;synthetic.button.button=SDL_BUTTON_LEFT;synthetic.button.x=240;synthetic.button.y=120;SDL_PushEvent(&synthetic);window.PollEvents();players.Route(hub);Check(!players.Find(a)->input.Pointer().down&&players.Find(b)->input.Touches().size()==1,"touch-generated mouse event cannot also control another player's physical mouse route");
 touch.type=SDL_FINGERUP;SDL_PushEvent(&touch);synthetic.type=SDL_MOUSEBUTTONUP;SDL_PushEvent(&synthetic);window.PollEvents();players.Route(hub);
 const int first=SDL_JoystickAttachVirtual(SDL_JOYSTICK_TYPE_GAMECONTROLLER,6,15,0),second=SDL_JoystickAttachVirtual(SDL_JOYSTICK_TYPE_GAMECONTROLLER,6,15,0);Check(first>=0&&second>=0,"two standard SDL virtual gamepads attached");auto* pa=SDL_JoystickOpen(first);auto* pb=SDL_JoystickOpen(second);window.PollEvents();std::vector<std::string> devices;for(auto& pair:hub.Devices())if(pair.second.kind=="gamepad"&&pair.second.connected)devices.push_back(pair.first);Check(devices.size()>=2,"adapter opens/enumerates both independent controller instances");if(devices.size()<2)return 1;players.Assign(a,hub,{devices[0],{}, {0,0,1,1}},error);players.Assign(b,hub,{devices[1],{}, {0,0,1,1}},error);players.Route(hub);
 SDL_JoystickSetVirtualAxis(pa,SDL_CONTROLLER_AXIS_LEFTX,-26000);SDL_JoystickSetVirtualAxis(pb,SDL_CONTROLLER_AXIS_LEFTX,26000);window.PollEvents();players.Route(hub);Check(players.Find(a)->input.Axis("move_x")<-.6f&&players.Find(b)->input.Axis("move_x")>.6f,"real SDL polls route opposite axes to distinct players");
 touch.type=SDL_FINGERDOWN;touch.tfinger.fingerId=99;touch.tfinger.x=.75f;touch.tfinger.y=.6f;SDL_PushEvent(&touch);window.PollEvents();players.Route(hub);Check(players.Find(b)->input.Touches().size()==1,"mixed touch/gamepad player has a live native touch before unrelated unplug");const auto heldTouch=players.Find(b)->input.Touches().empty()?0:players.Find(b)->input.Touches()[0].id;
 SDL_JoystickSetVirtualButton(pb,SDL_CONTROLLER_BUTTON_A,1);SDL_JoystickClose(pa);SDL_JoystickDetachVirtual(first);window.PollEvents();players.Route(hub);players.BeginFixedStep();Check(players.Find(a)->input.Axis("move_x")==0,"unplugged controller leaves neutral player input");Check(players.Find(b)->input.Axis("move_x")>.6f&&players.Find(b)->input.FixedAction("jump").pressed,"other player's new edge and held axis survive unrelated unplug");
 Check(players.Find(b)->input.Touches().size()==1&&players.Find(b)->input.Touches()[0].id==heldTouch,"legacy selected-controller reset cannot cancel another player's captured touch");touch.type=SDL_FINGERUP;SDL_PushEvent(&touch);window.PollEvents();players.Route(hub);
 auto removed=devices[0];SDL_JoystickClose(pb);int remaining=-1;for(int i=0;i<SDL_NumJoysticks();i++)if(SDL_JoystickIsVirtual(i))remaining=i;if(remaining>=0)SDL_JoystickDetachVirtual(remaining);window.PollEvents();players.Route(hub);const auto next=SDL_JoystickAttachVirtual(SDL_JOYSTICK_TYPE_GAMECONTROLLER,6,15,0);window.PollEvents();std::string replacement;for(auto& pair:hub.Devices())if(pair.second.kind=="gamepad"&&pair.second.connected)replacement=pair.first;Check(!replacement.empty()&&replacement!=removed&&!players.Assign(a,hub,{removed,{}, {0,0,1,1}},error),"native reconnect never revives retired device token");LocalPlayers fresh;fresh.devices=std::make_shared<InputDeviceHub>();window.Input().localDevices=fresh.devices;window.PollEvents();std::string newWorldDevice;for(auto& pair:fresh.devices->Devices())if(pair.second.kind=="gamepad"&&pair.second.connected)newWorldDevice=pair.first;Check(!newWorldDevice.empty()&&newWorldDevice!=replacement,"world replacement republishes attached controller under a fresh world token");const auto freshPlayer=fresh.Create("After reload",InputMap::Defaults(),error)->id;Check(fresh.Assign(freshPlayer,*fresh.devices,{newWorldDevice,{}, {0,0,1,1}},error),"new world can assign still-attached native controller without reconnect");auto* held=SDL_JoystickOpen(next);SDL_JoystickSetVirtualAxis(held,SDL_CONTROLLER_AXIS_LEFTX,26000);window.PollEvents();fresh.Route(*fresh.devices);Check(fresh.Find(freshPlayer)->input.Axis("move_x")>.6f&&!fresh.Find(freshPlayer)->input.Action("jump").pressed,"reloaded route preserves real held axis without fabricated button edge");SDL_JoystickClose(held);fresh.devices.reset();if(next>=0)SDL_JoystickDetachVirtual(next);window.PollEvents();players.devices.reset();window.PollEvents();Check(window.Input().localDevices.expired(),"returning to single-player releases optional hub/controller ownership");std::printf("%d checks %d failures\n",checks,failures);return failures?1:0;}
